SET NOCOUNT ON;
IF NOT EXISTS(SELECT 1 FROM dbo.__EFMigrationsHistory WHERE MigrationId=N'20260819132801_AddProviderAdvertisingRegionalPricingV105') THROW 51510,'V105 migration missing.',1;
IF COL_LENGTH('dbo.provider_advertising_rate_policies','province_unit_amount') IS NULL OR COL_LENGTH('dbo.provider_advertising_rate_policies','district_unit_amount') IS NULL OR COL_LENGTH('dbo.provider_advertising_rate_policies','regional_fee_cap_amount') IS NULL THROW 51511,'Regional rate columns missing.',1;
IF COL_LENGTH('dbo.provider_advertising_applications','base_fee_amount') IS NULL OR COL_LENGTH('dbo.provider_advertising_applications','regional_fee_amount') IS NULL OR COL_LENGTH('dbo.provider_advertising_applications','province_target_count') IS NULL OR COL_LENGTH('dbo.provider_advertising_applications','district_target_count') IS NULL THROW 51512,'Application fee snapshot columns missing.',1;
IF EXISTS(SELECT 1 FROM dbo.provider_advertising_rate_policies WHERE province_unit_amount<0 OR district_unit_amount<0 OR regional_fee_cap_amount<0) THROW 51513,'Invalid regional advertising rate.',1;
IF EXISTS(SELECT 1 FROM dbo.provider_advertising_applications WHERE base_fee_amount+regional_fee_amount<>fee_amount) THROW 51514,'Advertising fee snapshot mismatch.',1;
SELECT N'V105_OK' verification_result,(SELECT COUNT(*) FROM dbo.provider_advertising_rate_policies WHERE is_active=1) active_rate_count,(SELECT MIN(province_unit_amount) FROM dbo.provider_advertising_rate_policies WHERE is_active=1) province_unit_amount,(SELECT MIN(district_unit_amount) FROM dbo.provider_advertising_rate_policies WHERE is_active=1) district_unit_amount,(SELECT MAX(regional_fee_cap_amount) FROM dbo.provider_advertising_rate_policies WHERE is_active=1) regional_fee_cap_amount,(SELECT COUNT(*) FROM dbo.provider_advertising_applications) application_count;
GO
